import math
import cmath
import numpy as np
_cf = lambda u: np.exp(1j * u * (math.log(100) + 0.03) - 0.02 * u ** 2)
from scipy.special import ndtr as _ndtr


def _bs(K):
    d1 = (np.log(100 / K) + 0.07) / 0.2
    return 100 * _ndtr(d1) - K * np.exp(-0.05) * _ndtr(d1 - 0.2)


def _max_err(strikes, prices):
    m = (strikes > 50) & (strikes < 200)
    return float(np.max(np.abs(prices[m] - _bs(strikes[m]))))
